select count(sc1_0.id),coalesce(sum(case when sc1_0.review_status='CONFIRMED' then 1 else 0 end),0),coalesce(sum(case when sc1_0.review_status='DISMISSED' then 1 else 0 end),0),coalesce(sum(case when sc1_0.review_status='PENDING_REVIEW' and sc1_0.comparison_status not in ('PENDING','PROCESSING') and not((aj1_0.review_mode='AUTOMATIC' and aj1_0.automatic_applied_at is null and aj1_0.status in ('PENDING','RUNNING'))) then 1 else 0 end),0),coalesce(sum(case when sc1_0.review_status='PENDING_REVIEW' and (sc1_0.comparison_status in ('PENDING','PROCESSING') or (aj1_0.review_mode='AUTOMATIC' and aj1_0.automatic_applied_at is null and aj1_0.status in ('PENDING','RUNNING'))) then 1 else 0 end),0),coalesce(sum(case when sc1_0.review_status<>'PENDING_REVIEW' then 1 else 0 end),0),coalesce(sum(case when sc1_0.review_status='PENDING_REVIEW' then 1 else 0 end),0),coalesce(sum(case when sc1_0.review_status='PENDING_REVIEW' and sc1_0.match_status='AMBIGUOUS' then 1 else 0 end),0),coalesce(sum(case when sc1_0.review_status='PENDING_REVIEW' and (sc1_0.match_status='AMBIGUOUS' or sc1_0.comparison_status in ('FAILED','RECOMPARISON_REQUIRED')) then 1 else 0 end),0) from setting_candidates sc1_0 join analysis_jobs aj1_0 on aj1_0.id=sc1_0.analysis_job_id where sc1_0.work_id='32dbd752-8b1e-5ac4-8bfc-21f68e7ce40f' and aj1_0.batch_id='10fe7b4b-0093-5a1f-be13-aa729499dbd8' and ((NULL is null and aj1_0.source_kind='EPISODE') or aj1_0.id=NULL);
